  };

  // x52..68 across, z51 then z52. Row y4: the floor furniture.
  const floor = [
    // z51: fence at x56, bench x60..62, barrel x59, fence x64
    "....F..BSSS.F....",
    "................."  // z52 lane kept clear
  ];
  // y5: the standing lantern on the fence at x56 and x64, a pot on the barrel at x59
  const top = [
    "....L..P.....L...",
    "................."
  ];
  // y9: hanging lanterns down the lane (z52), each under the ceiling
  const ceiling = [
    ".................",
    " .h...h....h...h."
  ];
  layers(g, [52, 4, 51], legend, [floor, top, [".................", ".................", ".................", ".................", "................."], ceiling]);
}

